import { fail, redirect, error } from "@sveltejs/kit";
import { d as db } from "../../../../../../chunks/db.js";
import { g as getEmpresaId } from "../../../../../../chunks/get-empresa-id.js";
import "../../../../../../chunks/formData.js";
import { s as superValidate, z as zod, m as message } from "../../../../../../chunks/zod.js";
import { p as produtoSchema } from "../../../../../../chunks/produto.js";
import { s as serialize } from "../../../../../../chunks/utils3.js";
const load = async ({ params, request }) => {
  const empresaId = await getEmpresaId(request);
  const isNew = params.id === "novo";
  const [taxas, fornecedores, categorias] = await Promise.all([
    db.taxa.findMany(),
    db.fornecedor.findMany({ where: { empresaId } }),
    db.categoria.findMany({ where: { empresaId } })
  ]);
  let form;
  let productData = null;
  if (isNew) {
    form = await superValidate(zod(produtoSchema));
  } else {
    const produto = await db.produto.findUnique({
      where: { id: params.id },
      include: {
        taxa: true,
        _count: {
          select: {
            itemsVenda: true,
            ItemDocumento: true
          }
        }
      }
    });
    if (!produto || produto.empresaId !== empresaId) {
      throw error(404, "Produto não encontrado");
    }
    productData = {
      ...produto,
      precoUnitario: produto.precoUnitario.toNumber(),
      desconto: produto.desconto.toNumber(),
      taxa: produto.taxa ? { ...produto.taxa, valor: produto.taxa.valor.toNumber() } : null,
      canDelete: produto._count.itemsVenda === 0 && produto._count.ItemDocumento === 0
    };
    form = await superValidate(productData, zod(produtoSchema));
  }
  return serialize({
    isNew,
    form,
    taxas,
    fornecedores,
    categorias,
    produto: productData
  });
};
const actions = {
  save: async ({ params, request }) => {
    const empresaId = await getEmpresaId(request);
    const form = await superValidate(request, zod(produtoSchema));
    const isNew = params.id === "novo";
    if (!form.valid) {
      return fail(400, { form });
    }
    try {
      const data = {
        codigo: form.data.codigo,
        descricao: form.data.descricao,
        quantidade: form.data.quantidade,
        precoUnitario: form.data.precoUnitario,
        desconto: form.data.desconto,
        empresaId,
        taxaId: form.data.isento === "on" || !form.data.taxaId ? null : form.data.taxaId,
        fornecedorId: form.data.fornecedorId || null,
        tipo: form.data.tipo,
        isento: form.data.isento,
        motivoIsento: form.data.isento === "on" ? form.data.motivoIsento : "",
        categoriaId: form.data.categoriaId || null
      };
      if (isNew) {
        await db.produto.create({ data });
      } else {
        await db.produto.update({
          where: { id: params.id },
          data
        });
      }
      return message(form, isNew ? "Produto criado com sucesso!" : "Produto atualizado com sucesso!");
    } catch (err) {
      console.error("Error saving product:", err);
      return fail(500, {
        form,
        error: "Erro ao salvar produto"
      });
    }
  },
  delete: async ({ params, request }) => {
    const empresaId = await getEmpresaId(request);
    try {
      const produto = await db.produto.findUnique({
        where: { id: params.id },
        select: { empresaId: true }
      });
      if (!produto || produto.empresaId !== empresaId) {
        return fail(404, { error: "Produto não encontrado" });
      }
      await db.produto.delete({
        where: { id: params.id }
      });
      throw redirect(303, "/cadastros/produtos");
    } catch (err) {
      if (err instanceof Error && "status" in err) throw err;
      console.error("Error deleting product:", err);
      return fail(500, { error: "Erro ao excluir produto" });
    }
  }
};
export {
  actions,
  load
};
